    }

    /// The map itself failed (style or connection): for good.
    mutating func mapFailed() -> MapHealth? { set(.failed) }

    private mutating func set(_ h: MapHealth) -> MapHealth? {
        guard health != .failed, h != health else { return nil }
        health = h
        return h
    }
}

